from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
main_path = ROOT / 'app/src/main/java/com/goatpro/ip/MainActivity.kt'
enc_path = ROOT / 'app/src/main/java/com/goatpro/ip/H264Encoder.kt'
wm_path = ROOT / 'app/src/main/java/com/goatpro/ip/WatermarkOverlay.kt'


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise SystemExit(f'Patch point not found: {label}')
    return text.replace(old, new, 1)

# --- H264Encoder: direct ImageProxy -> MediaCodec fast path ---
enc = enc_path.read_text()
enc = replace_once(
    enc,
    'import android.media.MediaCodec\n',
    'import android.graphics.ImageFormat\nimport android.media.MediaCodec\n',
    'H264Encoder ImageFormat import'
)
enc = replace_once(
    enc,
    'import android.os.Build\n',
    'import android.os.Build\nimport androidx.camera.core.ImageProxy\n',
    'H264Encoder ImageProxy import'
)

marker = '''    fun requestKeyFrame() {\n'''
method = '''    /**\n     * Build 46 thermal fast path: feed CameraX YUV directly into MediaCodec.\n     * This avoids allocating a full 4K NV21 ByteArray and then converting/copying\n     * the same frame a second time before H.264 encode.\n     */\n    fun offerImageProxy(\n        image: ImageProxy,\n        presentationTimeNs: Long,\n        watermarkEnabled: Boolean\n    ): Boolean {\n        val encoder = codec ?: return false\n        if (!running.get()) return false\n        if (image.format != ImageFormat.YUV_420_888) return false\n        if (image.width != configuredWidth || image.height != configuredHeight) return false\n        if (image.planes.size < 3) return false\n\n        return try {\n            val index = encoder.dequeueInputBuffer(0)\n            if (index < 0) return false\n\n            val input = encoder.getInputBuffer(index) ?: run {\n                encoder.queueInputBuffer(index, 0, 0, presentationTimeNs / 1_000L, 0)\n                return false\n            }\n\n            val expected = image.width * image.height * 3 / 2\n            if (input.capacity() < expected) {\n                encoder.queueInputBuffer(index, 0, 0, presentationTimeNs / 1_000L, 0)\n                return false\n            }\n\n            input.clear()\n            writeImageProxyYuv(image, input, configuredColorFormat)\n            WatermarkOverlay.applyLuma(\n                input,\n                image.width,\n                image.height,\n                watermarkEnabled\n            )\n            input.position(expected)\n            encoder.queueInputBuffer(\n                index,\n                0,\n                expected,\n                presentationTimeNs / 1_000L,\n                0\n            )\n            true\n        } catch (_: Exception) {\n            false\n        }\n    }\n\n'''
enc = replace_once(enc, marker, method + marker, 'H264Encoder offerImageProxy insertion')

helper_marker = '''    private fun chooseColorFormat(colorFormats: IntArray): Int {\n'''
helpers = '''    private fun writeImageProxyYuv(\n        image: ImageProxy,\n        output: ByteBuffer,\n        colorFormat: Int\n    ) {\n        val width = image.width\n        val height = image.height\n        val planes = image.planes\n\n        writePlaneSequential(planes[0], width, height, output)\n\n        val planar =\n            colorFormat == MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Planar ||\n                colorFormat == MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420PackedPlanar\n\n        val chromaWidth = width / 2\n        val chromaHeight = height / 2\n        if (planar) {\n            writePlaneSequential(planes[1], chromaWidth, chromaHeight, output)\n            writePlaneSequential(planes[2], chromaWidth, chromaHeight, output)\n            return\n        }\n\n        // Existing semi-planar encoder path expects NV12 (UV). CameraX exposes\n        // U and V separately, often as pixelStride=2 views over NV21 memory.\n        // Interleave directly into the codec input buffer without an NV21 staging array.\n        val u = planes[1]\n        val v = planes[2]\n        val ub = u.buffer.duplicate()\n        val vb = v.buffer.duplicate()\n        for (row in 0 until chromaHeight) {\n            val uRow = row * u.rowStride\n            val vRow = row * v.rowStride\n            for (col in 0 until chromaWidth) {\n                output.put(ub.get(uRow + col * u.pixelStride))\n                output.put(vb.get(vRow + col * v.pixelStride))\n            }\n        }\n    }\n\n    private fun writePlaneSequential(\n        plane: ImageProxy.PlaneProxy,\n        width: Int,\n        height: Int,\n        output: ByteBuffer\n    ) {\n        val source = plane.buffer.duplicate()\n        if (plane.pixelStride == 1) {\n            for (row in 0 until height) {\n                val start = row * plane.rowStride\n                val rowBuffer = source.duplicate()\n                rowBuffer.position(start)\n                rowBuffer.limit(start + width)\n                output.put(rowBuffer)\n            }\n            return\n        }\n\n        for (row in 0 until height) {\n            val rowStart = row * plane.rowStride\n            for (col in 0 until width) {\n                output.put(source.get(rowStart + col * plane.pixelStride))\n            }\n        }\n    }\n\n'''
enc = replace_once(enc, helper_marker, helpers + helper_marker, 'H264Encoder direct YUV helpers')
enc_path.write_text(enc)

# --- WatermarkOverlay: render straight into encoder Y plane ---
wm = wm_path.read_text()
wm = replace_once(
    wm,
    'package com.goatpro.ip\n\n',
    'package com.goatpro.ip\n\nimport java.nio.ByteBuffer\n\n',
    'WatermarkOverlay ByteBuffer import'
)
insert_before = '''    private fun drawGlyph(\n'''
apply_luma = '''    /** Render the Free watermark directly into a MediaCodec input Y plane. */\n    fun applyLuma(\n        buffer: ByteBuffer,\n        width: Int,\n        height: Int,\n        enabled: Boolean\n    ) {\n        if (!enabled || width < 320 || height < 180) return\n\n        val scale = (width / 640).coerceIn(2, 6)\n        val glyphWidth = 5 * scale\n        val gap = scale\n        val textWidth = TEXT.length * (glyphWidth + gap) - gap\n        val textHeight = 7 * scale\n        val pad = 3 * scale\n        val margin = 8 * scale\n        val boxWidth = textWidth + pad * 2\n        val boxHeight = textHeight + pad * 2\n        val left = (width - boxWidth - margin).coerceAtLeast(0)\n        val top = (height - boxHeight - margin).coerceAtLeast(0)\n\n        for (y in top until (top + boxHeight).coerceAtMost(height)) {\n            val row = y * width\n            for (x in left until (left + boxWidth).coerceAtMost(width)) {\n                val index = row + x\n                val current = buffer.get(index).toInt() and 0xff\n                buffer.put(index, minOf(current, 70).toByte())\n            }\n        }\n\n        fun draw(rows: IntArray, x0: Int, y0: Int, yValue: Int) {\n            for (gy in rows.indices) {\n                val bits = rows[gy]\n                for (gx in 0 until 5) {\n                    if ((bits and (1 shl (4 - gx))) == 0) continue\n                    val px0 = x0 + gx * scale\n                    val py0 = y0 + gy * scale\n                    for (sy in 0 until scale) {\n                        val py = py0 + sy\n                        if (py !in 0 until height) continue\n                        val row = py * width\n                        for (sx in 0 until scale) {\n                            val px = px0 + sx\n                            if (px !in 0 until width) continue\n                            buffer.put(row + px, yValue.toByte())\n                        }\n                    }\n                }\n            }\n        }\n\n        var cursorX = left + pad\n        val originY = top + pad\n        for (ch in TEXT) {\n            val rows = glyphs[ch] ?: glyphs[' ']!!\n            draw(rows, cursorX + scale, originY + scale, 20)\n            draw(rows, cursorX, originY, 235)\n            cursorX += glyphWidth + gap\n        }\n    }\n\n'''
wm = replace_once(wm, insert_before, apply_luma + insert_before, 'WatermarkOverlay applyLuma')
wm_path.write_text(wm)

# --- MainActivity: RTSP-only direct feed + thermal cap + no concurrent MJPEG ---
main = main_path.read_text()
main = replace_once(
    main,
    'import android.os.Build\n',
    'import android.os.Build\nimport android.os.PowerManager\n',
    'MainActivity PowerManager import'
)
main = replace_once(
    main,
    '    private var preferredResolutionKey: String? = null\n\n',
    '    private var preferredResolutionKey: String? = null\n\n'
    '    private var cachedThermalStatus = PowerManager.THERMAL_STATUS_NONE\n'
    '    private var lastThermalCheckNs = 0L\n\n',
    'MainActivity thermal fields'
)

old_block = '''                            val profile = selectedQualityProfile\n                            val now = System.nanoTime()\n                            recordAnalysisFrame(now)\n\n                            val targetFps = streamTargetFps\n                            val frameIntervalNs = if (targetFps > 0) {\n                                1_000_000_000L / targetFps\n                            } else {\n                                0L\n                            }\n'''
new_block = '''                            val profile = selectedQualityProfile\n                            val now = System.nanoTime()\n                            recordAnalysisFrame(now)\n\n                            val requestedFps =\n                                if (streamTargetFps > 0) streamTargetFps else DEFAULT_START_FPS\n                            val targetFps = if (selectedResolution.highResolution) {\n                                thermalAwareHighResolutionFps(requestedFps, now)\n                            } else {\n                                streamTargetFps\n                            }\n                            val frameIntervalNs = if (targetFps > 0) {\n                                1_000_000_000L / targetFps\n                            } else {\n                                0L\n                            }\n'''
main = replace_once(main, old_block, new_block, 'MainActivity thermal FPS pacing')

old_processing = '''                            // CameraX rotates AUTO natively. The processed NV21 frame\n                            // is shared by MJPEG and the hardware H.264 path so we do not\n                            // perform the color/crop/rotation work twice.\n                            val manualRotation = selectedRotationMode.offsetDegrees\n                            val prepared = ImageUtils.imageProxyToNv21(\n                                image = image,\n                                rotationDegrees = manualRotation\n                            )?.let { frame ->\n                                WatermarkOverlay.apply(\n                                    frame,\n                                    watermarkEnabled\n                                )\n                            }\n\n                            if (prepared != null) {\n                                if (prepared.width != actualStreamWidth ||\n                                    prepared.height != actualStreamHeight\n                                ) {\n                                    actualStreamWidth = prepared.width\n                                    actualStreamHeight = prepared.height\n                                    runOnUiThread { updateStreamInfo() }\n                                }\n\n                                // Keep MJPEG for compatibility, but skip JPEG compression\n                                // when nobody is watching the MJPEG endpoint.\n                                if (server.videoClientCount() > 0) {\n                                    val jpegStartedNs = System.nanoTime()\n                                    val jpeg = ImageUtils.nv21ToJpeg(\n                                        prepared,\n                                        streamJpegQuality\n                                    )\n                                    val jpegElapsedNs = System.nanoTime() - jpegStartedNs\n                                    if (jpeg != null) {\n                                        server.offerFrame(jpeg.bytes)\n                                        recordEncodedFrame(jpeg.bytes.size, jpegElapsedNs)\n                                    }\n                                }\n\n                                // RTSP H.264 is encoded by MediaCodec. With only an RTSP\n                                // viewer connected there is no JPEG encode in the hot path.\n                                if (rtspServer.activeClientCount() > 0) {\n                                    val h264Fps =\n                                        (if (streamTargetFps > 0) streamTargetFps else 30)\n                                            .coerceIn(5, 120)\n                                    val bitrate =\n                                        if (streamBitrateBps > 0) {\n                                            streamBitrateBps\n                                        } else {\n                                            H264Encoder.recommendedBitrate(\n                                                prepared.width,\n                                                prepared.height,\n                                                h264Fps,\n                                                streamJpegQuality\n                                            )\n                                        }\n                                    if (h264Encoder.ensureStarted(\n                                            prepared.width,\n                                            prepared.height,\n                                            h264Fps,\n                                            bitrate\n                                        )\n                                    ) {\n                                        h264Encoder.offerNv21(prepared, now)\n                                    }\n                                } else if (h264Encoder.isRunning()) {\n                                    h264Encoder.stop()\n                                }\n                            }\n'''
new_processing = '''                            val manualRotation = selectedRotationMode.offsetDegrees\n                            val rtspActive = rtspServer.activeClientCount() > 0\n                            // Build 46: RTSP wins over MJPEG in 4K. Running both makes the\n                            // phone compress the same UHD frame twice and creates heat.\n                            val mjpegActive =\n                                server.videoClientCount() > 0 && !rtspActive\n                            val h264Fps =\n                                (if (targetFps > 0) targetFps else DEFAULT_START_FPS)\n                                    .coerceIn(5, 120)\n\n                            // Thermal fast path for rear 4K RTSP: CameraX -> MediaCodec\n                            // without the full-frame NV21 staging allocation/copy. AUTO\n                            // rotation is already applied by CameraX; manual rotations keep\n                            // the compatibility path below.\n                            val directRear4kRtsp =\n                                rtspActive &&\n                                    !selectedResolution.directFront4k &&\n                                    selectedResolution.size.width >= 3840 &&\n                                    selectedResolution.size.height >= 2160 &&\n                                    manualRotation == 0 &&\n                                    image.width == selectedResolution.size.width &&\n                                    image.height == selectedResolution.size.height\n\n                            if (directRear4kRtsp) {\n                                if (actualStreamWidth != image.width ||\n                                    actualStreamHeight != image.height\n                                ) {\n                                    actualStreamWidth = image.width\n                                    actualStreamHeight = image.height\n                                    runOnUiThread { updateStreamInfo() }\n                                }\n                                val bitrate =\n                                    if (streamBitrateBps > 0) streamBitrateBps\n                                    else H264Encoder.recommendedBitrate(\n                                        image.width,\n                                        image.height,\n                                        h264Fps,\n                                        streamJpegQuality\n                                    )\n                                if (h264Encoder.ensureStarted(\n                                        image.width,\n                                        image.height,\n                                        h264Fps,\n                                        bitrate\n                                    )\n                                ) {\n                                    h264Encoder.offerImageProxy(\n                                        image,\n                                        now,\n                                        watermarkEnabled\n                                    )\n                                }\n                                publishPerformanceStatsIfDue(System.nanoTime())\n                                return@setAnalyzer\n                            }\n\n                            // Compatibility path for MJPEG, manual rotation and lower\n                            // resolutions. Convert only when a consumer actually needs it.\n                            val needsPreparedFrame = mjpegActive || rtspActive\n                            val prepared = if (needsPreparedFrame) {\n                                ImageUtils.imageProxyToNv21(\n                                    image = image,\n                                    rotationDegrees = manualRotation\n                                )?.let { frame ->\n                                    WatermarkOverlay.apply(frame, watermarkEnabled)\n                                }\n                            } else {\n                                null\n                            }\n\n                            if (prepared != null) {\n                                if (prepared.width != actualStreamWidth ||\n                                    prepared.height != actualStreamHeight\n                                ) {\n                                    actualStreamWidth = prepared.width\n                                    actualStreamHeight = prepared.height\n                                    runOnUiThread { updateStreamInfo() }\n                                }\n\n                                if (mjpegActive) {\n                                    val jpegStartedNs = System.nanoTime()\n                                    val jpeg = ImageUtils.nv21ToJpeg(\n                                        prepared,\n                                        streamJpegQuality\n                                    )\n                                    val jpegElapsedNs = System.nanoTime() - jpegStartedNs\n                                    if (jpeg != null) {\n                                        server.offerFrame(jpeg.bytes)\n                                        recordEncodedFrame(jpeg.bytes.size, jpegElapsedNs)\n                                    }\n                                }\n\n                                if (rtspActive) {\n                                    val bitrate =\n                                        if (streamBitrateBps > 0) streamBitrateBps\n                                        else H264Encoder.recommendedBitrate(\n                                            prepared.width,\n                                            prepared.height,\n                                            h264Fps,\n                                            streamJpegQuality\n                                        )\n                                    if (h264Encoder.ensureStarted(\n                                            prepared.width,\n                                            prepared.height,\n                                            h264Fps,\n                                            bitrate\n                                        )\n                                    ) {\n                                        h264Encoder.offerNv21(prepared, now)\n                                    }\n                                }\n                            } else if (!rtspActive && h264Encoder.isRunning()) {\n                                h264Encoder.stop()\n                            }\n'''
main = replace_once(main, old_processing, new_processing, 'MainActivity rear 4K fast path')

helper_anchor = '''    private fun resetPerformanceStats() {\n'''
thermal_helper = '''    private fun thermalAwareHighResolutionFps(\n        requestedFps: Int,\n        nowNs: Long\n    ): Int {\n        if (Build.VERSION.SDK_INT < 29) return requestedFps.coerceIn(5, 60)\n        if (lastThermalCheckNs == 0L || nowNs - lastThermalCheckNs >= 1_000_000_000L) {\n            lastThermalCheckNs = nowNs\n            cachedThermalStatus = runCatching {\n                (getSystemService(Context.POWER_SERVICE) as PowerManager)\n                    .currentThermalStatus\n            }.getOrDefault(PowerManager.THERMAL_STATUS_NONE)\n        }\n        val cap = when {\n            cachedThermalStatus >= PowerManager.THERMAL_STATUS_SEVERE -> 20\n            cachedThermalStatus >= PowerManager.THERMAL_STATUS_MODERATE -> 24\n            else -> 60\n        }\n        return minOf(requestedFps.coerceIn(5, 60), cap)\n    }\n\n'''
main = replace_once(main, helper_anchor, thermal_helper + helper_anchor, 'MainActivity thermal helper')
main_path.write_text(main)

print('Build 46 rear 4K thermal fast path applied')
